const upsertCoverArt = `-- name: UpsertCoverArt :one

INSERT INTO cover_art (id, release_id, release_group_id, artist_id,
                       source_kind, uri, width, height, content_hash, is_preferred)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
ON CONFLICT (id) DO UPDATE SET
    source_kind  = excluded.source_kind,
    uri          = excluded.uri,
    width        = excluded.width,
    height       = excluded.height,
    content_hash = excluded.content_hash,
    is_preferred = excluded.is_preferred,
    fetched_at   = CURRENT_TIMESTAMP
RETURNING id, release_id, release_group_id, artist_id,
          source_kind, uri, width, height, content_hash, is_preferred, fetched_at
`

type UpsertCoverArtParams struct {
	ID             string
	ReleaseID      *string
	ReleaseGroupID *string
	ArtistID       *string
	SourceKind     string
	Uri            string
	Width          *int64
	Height         *int64
	ContentHash    []byte
	IsPreferred    bool
}

// Cover art + lyrics ------------------------------------------------------
func (q *Queries) UpsertCoverArt(ctx context.Context, arg UpsertCoverArtParams) (CoverArt, error) {
	row := q.db.QueryRowContext(ctx, upsertCoverArt,
		arg.ID,
		arg.ReleaseID,
		arg.ReleaseGroupID,
		arg.ArtistID,
		arg.SourceKind,
		arg.Uri,
		arg.Width,
		arg.Height,
		arg.ContentHash,
		arg.IsPreferred,
	)
	var i CoverArt
	err := row.Scan(
		&i.ID,
		&i.ReleaseID,
		&i.ReleaseGroupID,
		&i.ArtistID,
		&i.SourceKind,
		&i.Uri,
		&i.Width,
		&i.Height,
		&i.ContentHash,
		&i.IsPreferred,
		&i.FetchedAt,
	)
	return i, err
}

const upsertLyrics = `-- name: UpsertLyrics :exec
INSERT INTO lyrics (id, track_id, source, is_synced, language, content)
VALUES (?, ?, ?, ?, ?, ?)
ON CONFLICT (track_id, source) DO UPDATE SET
    is_synced  = excluded.is_synced,
    language   = excluded.language,
    content    = excluded.content,
    fetched_at = CURRENT_TIMESTAMP
`

